#!/usr/bin/env bash
# One-time setup for Codespaces / Dev Containers: .env, deps, schema, demo data.
# No secrets needed: everything points at the throwaway containers.
set -euo pipefail

if [ ! -f .env ]; then
  if [ -n "${CODESPACE_NAME:-}" ]; then
    APP_URL="https://${CODESPACE_NAME}-3000.${GITHUB_CODESPACES_PORT_FORWARDING_DOMAIN:-app.github.dev}"
  else
    APP_URL="http://localhost:3000"
  fi
  cat > .env <<ENV
# Generated by .devcontainer/setup.sh - local throwaway values only.
DATABASE_URL=postgres://reservo_app:reservo_app_dev_password@localhost:5432/reservo
DATABASE_ADMIN_URL=postgres://postgres:postgres@localhost:5432/reservo
BETTER_AUTH_SECRET=$(openssl rand -base64 32)
BETTER_AUTH_URL=${APP_URL}
NEXT_PUBLIC_APP_URL=${APP_URL}
DEMO_MODE=1
# Demo mode would only log emails; in the container we have Mailpit (port 8025).
MAIL_TRANSPORT=smtp
SMTP_HOST=mailpit
SMTP_PORT=1025
EMAIL_FROM="Reservo <no-reply@reservo.local>"
FAKE_PAYMENTS_WEBHOOK_SECRET=dev-fake-webhook-secret
ENV
  echo "Wrote .env (app URL: ${APP_URL})"
fi

npm ci
npm run db:migrate
npm run seed
